    if any(not member_id for member_id in member_ids) or len(set(member_ids)) != len(member_ids):
        return "duplicate or empty member id"

    rate_currencies = [rate.currency for rate in trip.rates]
    if len(set(rate_currencies)) != len(rate_currencies):
        return "duplicate rate currency"

    for rate in trip.rates:
        if not rate.base_per_unit.is_finite() or rate.base_per_unit <= 0:
            return "invalid exchange rate"

    base_rates = [rate for rate in trip.rates if rate.currency == trip.base_currency]
    if len(base_rates) != 1:
        return "missing base rate"

