        return "base rate must be 1"

    action_ids = []
    for action in trip.actions:
        if isinstance(action, ExpenseAction):
            action_ids.append(action.expense.expense_id)
        elif isinstance(action, PaymentAction):
            action_ids.append(action.payment.payment_id)

    if any(not action_id for action_id in action_ids) or len(set(action_ids)) != len(action_ids):
