        for entry in source_amounts
    ]
    floored_cents = [
        int(raw.to_integral_value(rounding=ROUND_FLOOR))
        for raw in raw_cents
    ]
    remaining = total_cents - sum(floored_cents)

    ranked_indices = sorted(
        range(len(expense.entries)),
