def settle_up(balances: dict[str, int]) -> tuple[Transfer, ...]:
    from functools import lru_cache

    if sum(balances.values()) != 0:
        raise ValueError("unbalanced")

    member_ids = tuple(sorted(member_id for member_id, balance in balances.items() if balance != 0))

    if len(member_ids) > MAX_SETTLEMENT_MEMBERS:
        raise ValueError("too many members")

    if not member_ids:
        return ()

    values = tuple(balances[member_id] for member_id in member_ids)
    size = len(member_ids)
    full_mask = (1 << size) - 1

    subset_sums = [0] * (1 << size)
    subset_members: list[tuple[str, ...]] = [()] * (1 << size)

    for mask in range(1, 1 << size):
        bit = mask & -mask
        index = bit.bit_length() - 1
        remainder = mask ^ bit
        subset_sums[mask] = subset_sums[remainder] + values[index]
        subset_members[mask] = subset_members[remainder] + (member_ids[index],)

    @lru_cache(maxsize=None)
    def best_partition(mask: int) -> tuple[tuple[str, ...], ...]:
        if mask == 0:
            return ()

        anchor = mask & -mask
        remainder = mask ^ anchor
        best: tuple[tuple[str, ...], ...] | None = None

        submask = remainder
        while True:
            group_mask = anchor | submask

            if subset_sums[group_mask] == 0:
                candidate = tuple(sorted((subset_members[group_mask],) + best_partition(mask ^ group_mask)))

                if (
                    best is None
                    or len(candidate) > len(best)
                    or (len(candidate) == len(best) and candidate < best)
                ):
                    best = candidate

            if submask == 0:
                break
            submask = (submask - 1) & remainder

        return best if best is not None else ()

    transfers: list[Transfer] = []

    for group in best_partition(full_mask):
        remaining = {member_id: balances[member_id] for member_id in group}

        while True:
            debtors = sorted(member_id for member_id, balance in remaining.items() if balance < 0)
            creditors = sorted(member_id for member_id, balance in remaining.items() if balance > 0)

            if not debtors:
                break

            debtor = debtors[0]
            creditor = creditors[0]
            cents = min(-remaining[debtor], remaining[creditor])

            transfers.append(Transfer(debtor, creditor, cents))
            remaining[debtor] += cents
            remaining[creditor] -= cents

    return tuple(sorted(transfers, key=lambda transfer: (
        transfer.from_member_id,
        transfer.to_member_id,
        transfer.cents,
    )))

