    if trip.closed:
        return (yield from throw(ClosedTripError(trip_id)))

    for validation in (
        validate_trip_configuration(trip),
        validate_payment(trip, payment),
        validate_new_action(trip, PaymentAction(payment)),
    ):
        if validation is not None:
            return (yield from throw(ValidationError(validation)))

    updated_trip = append_action(trip, PaymentAction(payment))
    repository.save_trip(updated_trip)
    return updated_trip

def record_payment(trip_id: str, payment: Payment):
    repository = yield from need(TripRepository)
    trip = repository.load_trip(trip_id)

