def undo_last_action(trip_id: str):
    repository = yield from need(TripRepository)
    trip = repository.load_trip(trip_id)

    if trip.closed:
        return (yield from throw(ClosedTripError(trip_id)))

    if not trip.actions:
        return (yield from throw(EmptyHistoryError(trip_id)))

    updated_trip = remove_last_action(trip)
    repository.save_trip(updated_trip)
    return updated_trip

def compute_balances(trip: Trip) -> dict[str, int]:
    balances = {member.member_id: 0 for member in trip.members}

    for action in trip.actions:
        if isinstance(action, ExpenseAction):
            deltas = expense_deltas(action.expense, trip)
        else:
            deltas = payment_deltas(action.payment)

        for member_id, delta in deltas.items():
            balances[member_id] += delta

    return balances
